def is_rect(cs):
    rs=[p[0] for p in cs]; cl=[p[1] for p in cs]
    r0,r1=min(rs),max(rs); c0,c1=min(cl),max(cl)
    return len(cs)==(r1-r0+1)*(c1-c0+1)

def f(gin):
