        for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
            a,b=r+dr,c+dc
            if 0<=a<h and 0<=b<w and (a,b) not in objset and (a,b) not in reach:
                reach.add((a,b)); st.append((a,b))
    out=[row[:] for row in g]
    for r in range(h):
        for c in range(w):
            if (r,c) not in objset and (r,c) not in reach:
                # try to extend to a neighbor rect color first
