import os,re
from collections import Counter,deque
np=__import__('numpy')
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load()
def comps(g,c):
    g=np.array(g); seen=set(); res=[]
    for i in range(g.shape[0]):
        for j in range(g.shape[1]):
            if (i,j) in seen or g[i,j]!=c: continue
            q=deque([(i,j)]); seen.add((i,j)); cs=[(i,j)]
            while q:
                x,y=q.popleft()
                for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                    u,v=x+dx,y+dy
                    if 0<=u<g.shape[0] and 0<=v<g.shape[1] and (u,v) not in seen and g[u,v]==c:
                        seen.add((u,v)); q.append((u,v)); cs.append((u,v))
            res.append(cs)
    return res
def is_rect(cs):
    rs=[p[0] for p in cs]; cl=[p[1] for p in cs]
    return len(cs)==(max(rs)-min(rs)+1)*(max(cl)-min(cl)+1)

def f(gin):
    g=[row[:] for row in gin]; h,w=len(g),len(g[0])
    bgc=Counter(x for row in g for x in row).most_common(1)[0][0]
    rects=[]
    for c in set(x for row in g for x in row):
        if c==bgc: continue
        for cc in comps(g,c):
            if is_rect(cc) and len(cc)>=4:
                for p in cc: rects.append((p[0],p[1],c))
    kept={(r,c) for r,c,_ in rects}
    out=[row[:] for row in g]
    for r in range(h):
        for c in range(w):
            if (r,c) not in kept:
                out[r][c]=bgc
    return out
